#pragma once
namespace snuw {
inline int legalDocumentTest(const fs::path& folder){try{
 auto raw=std::string("# Privacy\n\nFirst paragraph\ncontinues here.\n\n| Purpose | Data |\n| --- | --- |\n| Account | Nickname and email |\n| Escaped \\| pipe | <script src='https://invalid.test/x'>literal</script> |\n\n- Required use\n");for(int i=0;i<30;i++)raw+="\nLong paragraph for scroll and table layout. 개인정보 수집·보관·거부권 안내입니다.\n";
 auto blocks=legalBlocks(raw);if(!blocks[0].heading||blocks[1].cells[0]!=L"First paragraph continues here."||!blocks[2].table||!blocks[2].heading||blocks[4].cells[0]!=L"Escaped | pipe")throw std::runtime_error("Markdown structure lost");
 bool bounded=false;try{legalBlocks(std::string(128*1024+1,'x'));}catch(...){bounded=true;}if(!bounded)throw std::runtime_error("Unbounded legal document accepted");
 LegalDialog dialog(raw,"revision-2");dialog.create(false);if(IsWindowEnabled(dialog.agree))throw std::runtime_error("Consent was preselected");SendMessageW(dialog.window,WM_COMMAND,IDOK,0);if(dialog.accepted||!IsWindow(dialog.window))throw std::runtime_error("Missing required consent accepted");int layouts=0;
 for(int width:{380,580,900})for(int height:{440,800}){SetWindowPos(dialog.window,nullptr,0,0,width,height,SWP_NOZORDER|SWP_NOACTIVATE);dialog.layout();auto& view=dialog.document;RECT clip;GetClientRect(view.window,&clip);if(width==380){MoveWindow(view.window,16,68,220,clip.bottom,TRUE);GetClientRect(view.window,&clip);}for(auto& row:view.rows){if(row.height<=0||row.y<0||row.heights.size()!=row.block.cells.size())throw std::runtime_error("Legal table layout invalid");}if(width==380&&!view.rows[2].stacked)throw std::runtime_error("Narrow table did not stack");view.move(view.total);if(view.scroll!=std::max(0,view.total-int(clip.bottom)))throw std::runtime_error("Legal document end unreachable");HDC dc=CreateCompatibleDC(nullptr);BITMAPINFO info{};info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=clip.right;info.bmiHeader.biHeight=-clip.bottom;info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;info.bmiHeader.biCompression=BI_RGB;void* pixels=nullptr;auto bitmap=CreateDIBSection(dc,&info,DIB_RGB_COLORS,&pixels,nullptr,0);if(!bitmap||!pixels)throw std::runtime_error("Legal render bitmap failed");auto old=SelectObject(dc,bitmap);view.move(0);SendMessageW(view.window,WM_PRINTCLIENT,(WPARAM)dc,PRF_CLIENT);GdiFlush();int readable=0;auto data=(BYTE*)pixels;for(int i=0;i<clip.right*clip.bottom;i++)if(data[i*4]>140&&data[i*4+1]>140&&data[i*4+2]>140)readable++;SelectObject(dc,old);DeleteObject(bitmap);DeleteDC(dc);if(readable<100)throw std::runtime_error("Legal document text did not render");layouts++;}
 auto original=dialog.document.accessibleText;if(original.find(L"<script")==std::wstring::npos)throw std::runtime_error("Literal document content lost");
 SendMessageW(dialog.required,BM_SETCHECK,BST_CHECKED,0);SendMessageW(dialog.window,WM_COMMAND,101,0);if(!IsWindowEnabled(dialog.agree))throw std::runtime_error("Required consent control did not enable continue");SendMessageW(dialog.window,WM_COMMAND,IDOK,0);if(!dialog.accepted||dialog.hardware)throw std::runtime_error("Optional consent was implied");
 DeviceIdentity identity(folder);identity.accept("test","revision-2",sha256(raw),false);DeviceIdentity reopened(folder);if(!reopened.agreed("test","revision-2",sha256(raw))||reopened.agreed("test","revision-3",sha256(raw))||reopened.state["consents"]["test"].value("accepted_at",int64_t(0))<=0)throw std::runtime_error("Consent version/time persistence failed");
 deviceIdentity=std::make_shared<DeviceIdentity>(folder);bool invalid=false;try{reviewConsent("test","revision-2",sha256(raw),raw+"changed");}catch(...){invalid=true;}if(!invalid)throw std::runtime_error("Previously accepted digest skipped text verification");
if(accountErrorMessage("CONSENT_DOCUMENT_CHANGED").find(L"가입된 이메일")!=std::wstring::npos)throw std::runtime_error("Consent conflict confused with duplicate email");
 atomicWrite(folder/"legal-document-result.json",json{{"ok",true},{"layouts",layouts},{"markdown",true},{"required_gate",true},{"literal_html",true},{"version_time",true}}.dump());return 0;
 }catch(const std::exception& e){atomicWrite(folder/"legal-document-result.json",json{{"ok",false},{"error",e.what()}}.dump());return 1;}}
inline int consentRevisionTest(const fs::path& folder,const std::string& base,bool always){try{
 deviceIdentity=std::make_shared<DeviceIdentity>(folder);auto text=std::string("Consent revision fixture");deviceIdentity->accept(base,"revision-1",sha256(text),false);bool failed=false;
 try{beforeDeviceRequest(joinUrl(base,"/api/protected"),"test-key");}catch(const std::exception& e){failed=std::string(e.what()).find("다시 변경")!=std::string::npos;}
 if(failed!=always)throw std::runtime_error("Consent revision retry boundary failed");atomicWrite(folder/"consent-revision-result.json",json{{"ok",true},{"bounded",always}}.dump());return 0;
 }catch(const std::exception& e){atomicWrite(folder/"consent-revision-result.json",json{{"ok",false},{"error",e.what()}}.dump());return 1;}}
}
